public sealed class LoggingHandler(IHandler inner, ILogger<LoggingHandler> log)
    : IHandler
{
    public Task Handle(Command c)
    {
        log.LogInformation("Handling {Type}", c.GetType().Name);
        return inner.Handle(c);
    }
}

public abstract class HandlerDecorator(IHandler inner) : IHandler
{
    public virtual Task Handle(Command c) => inner.Handle(c);
}

public sealed class AuditProxy<T> : DispatchProxy
{
    protected override object? Invoke(MethodInfo m, object?[]? args) => m.Invoke(_target, args);
}
